  1→//! Shell refresh detection.
  2→//!
  3→//! This module provides functionality for detecting when PATH changes
  4→//! require a shell refresh.
  5→
  6→use std::collections::HashSet;
  7→
  8→/// Tracks PATH changes that require shell refresh.
  9→///
 10→/// # Example
 11→///
 12→/// ```
 13→/// use bivvy::shell::PathChangeDetector;
 14→///
 15→/// let mut detector = PathChangeDetector::new();
 16→/// detector.expect_additions(vec!["/nonexistent/path"]);
 17→///
 18→/// let result = detector.check();
 19→/// assert!(result.needs_refresh);
 20→/// assert!(!result.missing_paths.is_empty());
 21→/// ```
 22→pub struct PathChangeDetector {
 23→    /// PATH value at start of execution.
 24→    initial_path: String,
 25→    /// Expected path additions from steps.
 26→    expected_additions: HashSet<String>,
 27→}
 28→
 29→/// Result of checking for PATH changes.
 30→#[derive(Debug)]
 31→pub struct PathChangeResult {
 32→    /// Whether a shell refresh is needed.
 33→    pub needs_refresh: bool,
 34→    /// Paths that were expected but not found in current PATH.
 35→    pub missing_paths: Vec<String>,
 36→    /// Human-readable message explaining the change.
 37→    pub message: Option<String>,
 38→}
 39→
 40→impl PathChangeDetector {
 41→    /// Create a detector capturing the current PATH.
 42→    pub fn new() -> Self {
 43→        Self {
 44→            initial_path: std::env::var("PATH").unwrap_or_default(),
 45→            expected_additions: HashSet::new(),
 46→        }
 47→    }
 48→
 49→    /// Record that a step is expected to add paths.
 50→    pub fn expect_additions(&mut self, paths: impl IntoIterator<Item = impl Into<String>>) {
 51→        for path in paths {
 52→            self.expected_additions.insert(path.into());
 53→        }
 54→    }
 55→
 56→    /// Check if expected path additions are present.
 57→    pub fn check(&self) -> PathChangeResult {
 58→        let current_path = std::env::var("PATH").unwrap_or_default();
 59→        let separator = if cfg!(windows) { ';' } else { ':' };
 60→        let current_parts: HashSet<&str> = current_path.split(separator).collect();
 61→
 62→        let missing: Vec<String> = self
 63→            .expected_additions
 64→            .iter()
 65→            .filter(|p| !current_parts.contains(p.as_str()))
 66→            .cloned()
 67→            .collect();
 68→
 69→        let needs_refresh = !missing.is_empty();
 70→        let message = if needs_refresh {
 71→            Some(format!(
 72→                "Shell refresh needed to add {} path(s) to PATH",
 73→                missing.len()
 74→            ))
 75→        } else {
 76→            None
 77→        };
 78→
 79→        PathChangeResult {
 80→            needs_refresh,
 81→            missing_paths: missing,
 82→            message,
 83→        }
 84→    }
 85→
 86→    /// Get the initial PATH value.
 87→    pub fn initial_path(&self) -> &str {
 88→        &self.initial_path
 89→    }
 90→
 91→    /// Get the number of expected additions.
 92→    pub fn expected_count(&self) -> usize {
 93→        self.expected_additions.len()
 94→    }
 95→}
 96→
 97→impl Default for PathChangeDetector {
 98→    fn default() -> Self {
 99→        Self::new()
100→    }
101→}
102→
103→/// Information about what shell reload command to use.
104→///
105→/// # Example
106→///
107→/// ```no_run
108→/// use bivvy::shell::ShellReloadInfo;
109→///
110→/// // Detection depends on SHELL environment variable (Unix only)
111→/// // std::env::set_var("SHELL", "/bin/bash");
112→/// if let Some(info) = ShellReloadInfo::detect() {
113→///     assert_eq!(info.shell, "bash");
114→///     assert!(info.reload_command.contains("source"));
115→/// }
116→/// ```
117→#[derive(Debug, Clone)]
118→pub struct ShellReloadInfo {
119→    /// Shell name (bash, zsh, fish).
120→    pub shell: String,
121→    /// Command to reload the shell.
122→    pub reload_command: String,
123→    /// Config file that was modified.
124→    pub config_file: String,
125→}
126→
127→impl ShellReloadInfo {
128→    /// Detect the current shell and provide reload info.
129→    pub fn detect() -> Option<Self> {
130→        let shell_path = std::env::var("SHELL").ok()?;
131→        let shell_name = std::path::Path::new(&shell_path).file_name()?.to_str()?;
132→
133→        let (reload_command, config_file) = match shell_name {
134→            "bash" => ("source ~/.bashrc", "~/.bashrc"),
135→            "zsh" => ("source ~/.zshrc", "~/.zshrc"),
136→            "fish" => (
137→                "source ~/.config/fish/config.fish",
138→                "~/.config/fish/config.fish",
139→            ),
140→            _ => return None,
141→        };
142→
143→        Some(Self {
144→            shell: shell_name.to_string(),
145→            reload_command: reload_command.to_string(),
146→            config_file: config_file.to_string(),
147→        })
148→    }
149→
150→    /// Get an alternative reload method (exec the shell).
151→    pub fn exec_command(&self) -> String {
152→        format!("exec {}", self.shell)
153→    }
154→}
155→
156→#[cfg(test)]
157→mod tests {
158→    use super::*;
159→
160→    // Mutex to serialize tests that modify SHELL env var (unix only)
161→    #[cfg(unix)]
162→    use std::sync::Mutex;
163→    #[cfg(unix)]
164→    static SHELL_MUTEX: Mutex<()> = Mutex::new(());
165→
166→    #[cfg(unix)]
167→    fn with_shell_env<F, R>(shell_path: &str, f: F) -> R
168→    where
169→        F: FnOnce() -> R,
170→    {
171→        let _guard = SHELL_MUTEX.lock().unwrap();
172→        let old_shell = std::env::var("SHELL").ok();
173→        std::env::set_var("SHELL", shell_path);
174→        let result = f();
175→        match old_shell {
176→            Some(v) => std::env::set_var("SHELL", v),
177→            None => std::env::remove_var("SHELL"),
178→        }
179→        result
180→    }
181→
182→    #[test]
183→    fn detects_missing_path_additions() {
184→        let mut detector = PathChangeDetector::new();
185→        detector.expect_additions(vec!["/nonexistent/path/here"]);
186→
187→        let result = detector.check();
188→
189→        assert!(result.needs_refresh);
190→        assert!(result
191→            .missing_paths
192→            .contains(&"/nonexistent/path/here".to_string()));
193→    }
194→
195→    #[test]
196→    fn no_refresh_when_paths_present() {
197→        // Get a path that we know is in the current PATH
198→        let current_path = std::env::var("PATH").unwrap_or_default();
199→        let separator = if cfg!(windows) { ';' } else { ':' };
200→        let existing_path = current_path
201→            .split(separator)
202→            .next()
203→            .unwrap_or("")
204→            .to_string();
205→
206→        // Only run if we actually have a path to test
207→        if existing_path.is_empty() {
208→            return;
209→        }
210→
211→        let mut detector = PathChangeDetector::new();
212→        detector.expect_additions(vec![existing_path]);
213→
